const out = {};
async function describe(id, label) {
  const n = await figma.getNodeByIdAsync(id);
  if (!n) { out[label] = 'NOT FOUND'; return; }
  const d = { name: n.name, type: n.type, w: n.width, h: n.height };
  if ('fills' in n) d.fills = JSON.parse(JSON.stringify(n.fills));
  if ('strokes' in n) d.strokes = JSON.parse(JSON.stringify(n.strokes));
  if ('strokeWeight' in n) d.strokeWeight = n.strokeWeight;
  if ('cornerRadius' in n) d.cornerRadius = n.cornerRadius;
  if ('effects' in n) d.effects = JSON.parse(JSON.stringify(n.effects));
  if ('layoutMode' in n) d.layoutMode = n.layoutMode;
  if (n.type === 'TEXT') {
    d.characters = n.characters;
    d.fontSize = n.fontSize;
    d.fontName = n.fontName;
    d.textAlignHorizontal = n.textAlignHorizontal;
    try { d.fills = JSON.parse(JSON.stringify(n.fills)); } catch(e){}
  }
  if ('children' in n) d.children = n.children.map(c => ({ id: c.id, name: c.name, type: c.type, x: c.x, y: c.y, w: c.width, h: c.height }));
  out[label] = d;
}
